//绑定事件
$("run").onclick = function(){
    lushu.start();
	timedCount1();
	timedCount2();
	timedCount3();
	timedCount4();
	timedCountHour();
	timedCountMin();
	//showdate();
	
	//timedCountSecond();
	onad();
}
$("stop").onclick = function(){
    lushu.stop();
}
$("pause").onclick = function(){
    lushu.pause();
}

function $(element){
    return document.getElementById(element);
}